parse-doc xlsx documents/ghg-data-workbook-fy2024.xlsx; python3 - <<EOF
import openpyxl
wb=openpyxl.load_workbook("documents/ghg-data-workbook-fy2024.xlsx")
for ws in wb:
  print("##",ws.title,ws.dimensions)
  for row in ws.iter_rows():
    for c in row:
      if c.value is not None and (isinstance(c.value,str) and c.value.startswith("=") or c.comment):
        print(c.coordinate,repr(c.value),c.comment.text if c.comment else "")
EOF
